  if($method==='POST'&&$path==='/codes/activate'){$r=$codes[$body['code']];if($r['recipient_login']!==gc_credentials($merchant)['recipient_login']||$body['site_id']!==gc_credentials($merchant)['site_id'])throw new VdarRejected('INVALID_RECIPIENT');$codes[$body['code']]['status']='activated';return ['success'=>true,'operation_id'=>gc_uuid(),'currency_code'=>'RUB','activated_amount'=>$r['amount'],'commission_charged'=>'5.00','activated_at'=>gmdate('c')];}
